// Separate media files from the serializable edit graph. IndexedDB is optional, never assumed.
function db(){return new Promise((resolve,reject)=>{try{const r=indexedDB.open('vault-buddy-editor-media-v2',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}catch(e){reject(e)}})}
