function syncMedia(force=false){const active=new Set();for(const c of project.clips.filter(c=>c.start_ms>ui.time&&c.start_ms<ui.time+900)){const r=runtime(c);if(r&&!r.active&&r.el.readyState>=1&&Math.abs(r.el.currentTime-c.in_ms/1000)>.03){try{r.el.currentTime=c.in_ms/1000}catch{}}}for(const c of activeClips()){const a=asset(c.asset_id);if(a.media_type==='image'||a.builtin&&a.kind==='video')continue;const r=runtime(c);if(!r||r.failed)continue;active.add(c.id);if(audioCtx)wireAudio(r);const desired=clamp(sourceTime(c)/1000,0,Math.max(0,(r.el.duration||a.duration_ms/1000)-.005));if(force||!r.active||Math.abs(r.el.currentTime-desired)>(ui.playing?.18:.025)){try{r.el.currentTime=desired}catch{}}r.el.playbackRate=(ui.exporting?1:ui.rate)*clipSpeed(c);r.el.preservesPitch=c.preserve_pitch!==false;if(r.gain)r.gain.gain.setTargetAtTime(clipGain(c),audioCtx.currentTime,.012);if(ui.playing&&r.el.paused&&!r.pending){r.pending=true;r.el.play().catch(()=>{if(ui.playing)toast('Playback was blocked. Press Play again after choosing the media.')}).finally(()=>r.pending=false)}if(!ui.playing)r.el.pause();r.active=true}for(const [id,r] of runtimes){if(!active.has(id)){r.el.pause();r.active=false;if(r.gain)r.gain.gain.setTargetAtTime(0,audioCtx.currentTime,.006)}if(!clip(id)||r.asset_id!==clip(id)?.asset_id||(!active.has(id)&&Math.abs((clip(id)?.start_ms||0)-ui.time)>5000&&Math.abs(end(clip(id)||{start_ms:0,in_ms:0,out_ms:0})-ui.time)>5000)){r.el.pause();r.node?.disconnect();r.gain?.disconnect();r.el.removeAttribute('src');r.el.load();runtimes.delete(id)}}if(mixBus)mixBus.gain.setTargetAtTime(project.master_gain,audioCtx.currentTime,.01);if(monitorBus)monitorBus.gain.setTargetAtTime(ui.monitorMuted?0:1,audioCtx.currentTime,.01)}
