 html=`<div class="selection-title"><span class="glyph">${svg(a.kind==='video'?'video':'music')}</span><span class="grow"><b>${esc(c.name)}</b><small>${esc(t.name)} · ${(d/1000).toFixed(1)}s</small></span></div><div class="property-tabs">${(a.kind==='video'?['properties','layout','fades','audio']:['properties','fades','audio']).map(k=>`<button data-property-tab="${k}" class="${ui.propertyTab===k?'active':''}" aria-pressed="${ui.propertyTab===k}">${k==='properties'?'Clip':k==='layout'?'Layout':k==='fades'?'Fades':'Audio'}</button>`).join('')}</div>`;if(t.locked)html+='<p class="field-help warning">Track locked. Unlock it using the padlock below.</p>';
