canvas.addEventListener('pointerdown',ev=>{if(ui.exporting||ui.review||ev.button!==0)return;pause();const r=canvas.getBoundingClientRect(),px=(ev.clientX-r.left)/r.width,py=(ev.clientY-r.top)/r.height,visible=activeClips().filter(c=>track(c.track_id)?.kind==='video'&&track(c.track_id)?.visible).sort((a,b)=>project.tracks.indexOf(track(a.track_id))-project.tracks.indexOf(track(b.track_id)));for(const c of visible){if(px<c.x||px>c.x+c.w||py<c.y||py>c.y+c.h)continue;const point=pointInClip(ev,c);const effects=effectsFor(c).slice().reverse();const selected=effects.find(e=>e.id===ui.selected?.id);if(selected){effects.splice(effects.indexOf(selected),1);effects.unshift(selected)}for(const e of effects){if(!hitEffect(point,e))continue;if(!editable(c,true))return;ui.selected={type:'effect',id:e.id};let mode='move';if(e.kind==='arrow'){if(Math.hypot(point.x-e.x2*W,point.y-e.y2*H)<22)mode='end';else if(Math.hypot(point.x-e.x*W,point.y-e.y*H)<22)mode='start'}else if(['text','highlight','spotlight','mask'].includes(e.kind)){const b=bounds(e);if(Math.hypot(point.x-b.x-b.w,point.y-b.y-b.h)<25)mode='size'}previewDrag={kind:'effect',id:e.id,clip_id:c.id,original:deep(e),before:deep(project),point,mode};renderInspector();renderTimeline();paint();ev.preventDefault();return}if(c.w<.999){if(!editable(c,true))return;ui.selected={type:'clip',id:c.id};const edges=[['tl',c.x,c.y],['tr',c.x+c.w,c.y],['bl',c.x,c.y+c.h],['br',c.x+c.w,c.y+c.h]],edge=edges.find(([key,x,y])=>Math.abs((px-x)*r.width)<16&&Math.abs((py-y)*r.height)<16)?.[0];previewDrag={kind:'video',id:c.id,original:deep(c),before:deep(project),point:{x:px,y:py},mode:edge||'move'};renderInspector();renderTimeline();paint();ev.preventDefault();return}}});
function movePreview(ev){const d=previewDrag;if(d.kind==='video'){const r=canvas.getBoundingClientRect(),p={x:(ev.clientX-r.left)/r.width,y:(ev.clientY-r.top)/r.height},c=clip(d.id),o=d.original;if(d.mode!=='move'){const left=d.mode.endsWith('l'),top=d.mode.startsWith('t'),ratio=o.h/o.w,anchorX=left?o.x+o.w:o.x,anchorY=top?o.y+o.h:o.y,dx=(p.x-d.point.x)*(left?-1:1),dy=(p.y-d.point.y)*(top?-1:1)/ratio,delta=Math.abs(dx)>Math.abs(dy)?dx:dy,maxW=Math.min(left?anchorX:1-anchorX,(top?anchorY:1-anchorY)/ratio);c.w=clamp(o.w+delta,Math.max(.1,.1/ratio),maxW);c.h=c.w*ratio;c.x=left?anchorX-c.w:anchorX;c.y=top?anchorY-c.h:anchorY;}else{c.x=clamp(o.x+p.x-d.point.x,0,1-c.w);c.y=clamp(o.y+p.y-d.point.y,0,1-c.h)}}else{const c=clip(d.clip_id),p=pointInClip(ev,c),dx=(p.x-d.point.x)/W,dy=(p.y-d.point.y)/H,e=project.effects.find(e=>e.id===d.id),o=d.original;if(e.kind==='arrow'){if(d.mode==='start'){e.x=clamp(o.x+dx,0,1);e.y=clamp(o.y+dy,0,1)}else if(d.mode==='end'){e.x2=clamp(o.x2+dx,0,1);e.y2=clamp(o.y2+dy,0,1)}else{const sx=clamp(dx,-Math.min(o.x,o.x2),1-Math.max(o.x,o.x2)),sy=clamp(dy,-Math.min(o.y,o.y2),1-Math.max(o.y,o.y2));e.x=o.x+sx;e.x2=o.x2+sx;e.y=o.y+sy;e.y2=o.y2+sy}}else if(d.mode==='size'){e.w=clamp(o.w+dx,.04,1-e.x);if(e.kind!=='text')e.h=clamp(o.h+dy,.03,1-e.y)}else{const maxX=['text','highlight','spotlight','mask'].includes(e.kind)?1-(e.w||.05):1,maxY=['highlight','spotlight','mask'].includes(e.kind)?1-e.h:1;e.x=clamp(o.x+dx,0,maxX);e.y=clamp(o.y+dy,0,maxY)}}paint()}
function finishPreviewDrag(cancel=false){const d=previewDrag;if(!d)return;previewDrag=null;if(cancel)project=d.before;else{try{validate(project);pushHistory(d.before,'Position '+d.kind)}catch(e){project=d.before;toast(e.message)}}render()}
function setTimelineHeight(h){h=clamp(h,170,Math.max(170,Math.min(540,innerHeight-370)));document.documentElement.style.setProperty('--timeline',Math.round(h)+'px');$('#resizeBar').setAttribute('aria-valuenow',String(Math.round(h)));fitCanvas()}
$('#resizeBar').addEventListener('pointerdown',ev=>{resizeDrag={y:ev.clientY,height:$('.timeline').getBoundingClientRect().height};ev.preventDefault()});
$('#resizeBar').addEventListener('keydown',ev=>{if(['ArrowUp','ArrowDown'].includes(ev.key)){ev.preventDefault();setTimelineHeight(clamp($('.timeline').getBoundingClientRect().height+(ev.key==='ArrowUp'?25:-25),210,Math.min(540,innerHeight-260)))}});
let draggedAsset=null;document.addEventListener('dragstart',ev=>{const card=ev.target.closest('[data-asset]');if(!card)return;draggedAsset=card.dataset.asset;ev.dataTransfer.setData('text/plain',draggedAsset);ev.dataTransfer.effectAllowed='copy'});document.addEventListener('dragover',ev=>{if(ev.target.closest('[data-lane],.library')){ev.preventDefault();ev.dataTransfer.dropEffect='copy'}});document.addEventListener('drop',ev=>{const lane=ev.target.closest('[data-lane]'),library=ev.target.closest('.library');if(!lane&&!library)return;ev.preventDefault();if(ev.dataTransfer.files.length){importFiles([...ev.dataTransfer.files]);return}const id=draggedAsset||ev.dataTransfer.getData('text/plain');if(lane&&asset(id)){const t=track(lane.dataset.lane);if(t.kind!==asset(id).kind){toast('Use a '+asset(id).kind+' track for this media.');return}addAsset(id,t.id,timelineTime(ev))}draggedAsset=null});
// Dialogs, guide and portable edit package.
function openDialog(id){pause();const dialog=typeof id==='string'?$(id):id;dialog.showModal();return dialog}
function closeDialog(d){if(!d)return;if(d.id==='webcamDialog'){requestCloseWebcam();return;}if(d.id==='saveDialog'&&ui.exporting){cancelExport();return}d.close()}
function promptText(title,label,value,callback){editCallback=callback;$('#editDialogTitle').textContent=title;$('#editDialogLabel').textContent=label;$('#editText').value=value;openDialog('#editDialog');$('#editText').focus();$('#editText').select()}
function confirmAction(title,message,callback){confirmCallback=callback;$('#confirmTitle').textContent=title;$('#confirmText').textContent=message;openDialog('#confirmDialog')}
$('#editForm').addEventListener('submit',ev=>{ev.preventDefault();const v=$('#editText').value.trim();if(!v)return;$('#editDialog').close();editCallback?.(v);editCallback=null});$('#confirmButton').addEventListener('click',()=>{$('#confirmDialog').close();const fn=confirmCallback;confirmCallback=null;fn?.()});
function addMarker(){let c=selectedClip();if(!c||ui.time<c.start_ms||ui.time>=end(c))c=activeClips().filter(c=>track(c.track_id)?.kind==='video').at(-1);if(!editable(c,true))return;const when=clamp(sourceTime(c),c.in_ms,c.out_ms-1);promptText('Add a chapter','Chapter title','New chapter',title=>change(()=>project.markers.push({id:uid('chapter'),clip_id:c.id,source_ms:Math.round(when),title}),'Add chapter'))}
function mdText(s){return String(s).replace(/[\r\n]/g,' ').replace(/([\[\]_*`<>|])/g,'\\$1')}
function noteText(extension='webm',hasVideo=false){const name=safeBase(project.title);return `---\ntitle: ${JSON.stringify(project.title)}\ntype: video-tutorial\neditor_schema: vault-buddy-video-project/2\nduration_seconds: ${(duration()/1000).toFixed(3)}\nvideo_tracks: ${project.tracks.filter(t=>t.kind==='video').length}\naudio_tracks: ${project.tracks.filter(t=>t.kind==='audio').length}\n---\n\n# ${mdText(project.title)}\n\n${hasVideo?`![[${name}.${extension}]]`:'> This edit package does not include a rendered video. Render it in the editor or with the native pipeline before publishing.'}\n\n## Chapters\n\n${visibleMarkers().map(m=>`- **${fmt(m.output,true)}** — ${mdText(m.title)}`).join('\n')||'No chapters have been added yet.'}\n\n## Editable project\n\n[[${name}.edit.json]]\n\n## Source media\n\n${project.assets.filter(a=>project.clips.some(c=>c.asset_id===a.id)).map(a=>`- ${mdText(a.name)}${a.builtin?' (built-in sample)':''}`).join('\n')}\n\n> Review export: 720p, browser-composited. Native vault saving is not connected in this browser editor.\n`}
function showNote(){$('#notePreview').textContent=noteText();openDialog('#noteDialog')}
function healthHTML(){const h=projectHealth(),hidden=project.tracks.filter(t=>!t.visible&&t.kind==='video').length,solo=project.tracks.filter(t=>t.solo).length;const checks=[{ok:!!h.clips,title:h.clips?`${h.clips} editable clips`:'Timeline is empty',detail:'Original source media is never trimmed or overwritten.'},{ok:!h.missing.length,title:h.missing.length?`${h.missing.length} source files need relinking`:'Source media is available',detail:h.missing.length?h.missing.map(a=>a.name).join(', '):'All currently used assets are built-in or connected.'},{ok:h.hasVideo,title:h.hasVideo?'Visible video is present':'No visible video clips',detail:hidden?`${hidden} video tracks are hidden and will not appear in export.`:'Track stacking and annotations are included in the preview.'},{ok:!h.gaps.length,title:h.gaps.length?'Video coverage gaps need review':'No uncovered video intervals',detail:h.gaps.length?h.gaps.map(g=>fmt(g[0],true)+'–'+fmt(g[1],true)).join(', '):'Visible video covers the project duration.'},{ok:!solo,title:solo?`${solo} soloed tracks will define the audio mix`:'Full audio mix selected',detail:'Track mute and solo apply to export. Monitoring mute does not.'},{ok:!!visibleMarkers().length,title:visibleMarkers().length?`${visibleMarkers().length} chapters in the note`:'No chapters yet',detail:'Chapters are optional. Captions / subtitles are not implemented.'}];return checks.map(c=>`<div class="review-check ${c.ok?'':'warn'}">${svg(c.ok?'check':'warning')}<span><b>${esc(c.title)}</b><small>${esc(c.detail)}</small></span></div>`).join('')}
function supportedMime(){if(typeof MediaRecorder==='undefined'||!canvas.captureStream)return null;for(const m of ['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'])if(MediaRecorder.isTypeSupported(m))return m;return null}
function openSave(reviewOnly=false){pause();const h=projectHealth(),warnings=[...(h.gaps.length?[`Video has uncovered intervals: ${h.gaps.map(g=>fmt(g[0],true)+'–'+fmt(g[1],true)).join(', ')}.`]:[]),...(project.tracks.some(t=>t.solo)?['Solo is active. Only soloed tracks will contribute audio.']:[])],can=!!supportedMime()&&h.clips>0&&h.hasVideo&&!h.missing.length&&h.duration<=180000;$('#saveBody').innerHTML=`${reviewOnly?healthHTML():`<div class="callout"><b>Prototype boundary</b><br>This downloads a local ZIP. It does not write into your vault. Browser video rendering is real-time, 720p, and limited to 3 minutes.</div><div class="fieldpair"><label class="field">Tutorial title<input id="exportTitle" value="${esc(project.title)}" maxlength="160"></label><label class="field">Vault<input id="exportVault" value="${esc(project.destination.vault)}" maxlength="80"></label></div><label class="field">Folder inside vault<input id="exportFolder" value="${esc(project.destination.folder)}" placeholder="Intake/Screen"></label><label class="check-row"><input type="checkbox" id="includeVideo" ${can?'checked':'disabled'}>Render the edited video with all visible tracks and audio</label>${!can?`<p class="field-help warning">${h.missing.length?'Relink missing source files before rendering.':h.duration>180000?'This edit is over the 3-minute browser review limit.':'Video rendering needs a supported browser and at least one visible video clip.'} The editable package can still be downloaded.</p>`:''}${warnings.length?`<p class="field-help warning">${warnings.map(esc).join('<br>')}</p>`:''}<label class="check-row"><input type="checkbox" id="includeSources">Include imported originals for a portable package</label><p class="field-help">Without originals, imported files must be relinked when reopening on another device. Built-in sample media is regenerated automatically.</p><div class="export-list"><div class="row">${svg('video')}<span class="grow">Review video</span><span class="pill">${supportedMime()?.includes('mp4')?'MP4':'WEBM'} · 720p</span></div><div class="row">${svg('file')}<span class="grow">Companion note + chapter timestamps</span><span class="pill">MD</span></div><div class="row">${svg('layers')}<span class="grow">Editable multi-track project</span><span class="pill">JSON</span></div><div class="row">${svg('camera')}<span class="grow">Annotated poster frame</span><span class="pill">PNG</span></div></div><p id="exportError" class="error-text" role="alert"></p>`}`;$('#saveFooter').innerHTML=reviewOnly?`<button class="btn" data-action="close">Back to edit</button><button class="primary" data-action="save">Continue to export</button>`:`<button class="btn" data-action="close">Keep editing</button><button class="primary" data-action="downloadPackage">${svg('download')}Download package</button>`;$('#saveTitle').textContent=reviewOnly?'Before you publish':'Ready for your vault';if(!$('#saveDialog').open)openDialog('#saveDialog')}
function frameBlob(){return new Promise((resolve,reject)=>{const c=document.createElement('canvas');c.width=W;c.height=H;paint(c.getContext('2d'),false);c.toBlob(b=>b?resolve(b):reject(new Error('Could not create the poster frame.')),'image/png')})}
async function snapshot(){try{downloadBlob(await frameBlob(),safeBase(project.title)+'-'+fmt(ui.time,true).replace(':','-')+'.png');toast('Annotated frame downloaded.')}catch(e){toast(e.message)}}
async function packageFiles(videoBlob=null,extension='webm',poster=null,includeSources=false){const base=safeBase(project.title),folder=safeFolder(project.destination.folder),path=folder?folder+'/':'',files=[{name:path+base+'.edit.json',data:JSON.stringify(project,null,2)},{name:path+base+'.md',data:noteText(extension,!!videoBlob)},{name:path+base+'.png',data:new Uint8Array(await(poster||await frameBlob()).arrayBuffer())}];if(videoBlob)files.push({name:path+base+'.'+extension,data:new Uint8Array(await videoBlob.arrayBuffer())});const manifest={schema:'vault-buddy-review-package/2',title:project.title,rendered:!!videoBlob,rendered_type:videoBlob?.type||null,source_files:[]};if(includeSources){let total=0;for(const a of project.assets.filter(a=>!a.builtin&&!a.linked_asset)){const f=media.get(a.id)?.file;if(f)total+=f.size}if(total>200*1024*1024)throw new Error('Originals exceed the 200 MB packaging limit. Export without originals, and copy them alongside the edit yourself.');for(const a of project.assets.filter(a=>!a.builtin&&!a.linked_asset)){const f=media.get(a.id)?.file;if(f){const name='Sources/'+a.id+'-'+safeBase(a.name);files.push({name,data:new Uint8Array(await f.arrayBuffer())});manifest.source_files.push({asset_id:a.id,name,original_name:a.name})}}}files.push({name:'manifest.json',data:JSON.stringify(manifest,null,2)},{name:'READ-ME.txt',data:'VAULT BUDDY — LOCAL REVIEW PACKAGE\n\nNo file has been written to an Obsidian vault. Copy the destination folder into your vault explicitly.\nOpen the .edit.json in the editor. When needed, relink original media from Sources using manifest.json.\nImported videos may have separate audio clips; all timing edits are non-destructive.\nBrowser rendering is not a native, frame-accurate delivery master. It can drop frames under load.\nNo captions, transcription or secure redaction have been generated. Review the entire video before sharing.\n'});const blob=await makeZip(files);return{blob,name:base+'-vault-package.zip',files:files.map(f=>f.name)}}
function showReady(pack){lastPackage=pack;$('#saveTitle').textContent='Your package is ready';$('#saveBody').innerHTML=`<div class="callout"><b>Downloaded locally.</b><br>Nothing was written into your vault. Open the ZIP, review the files, and copy the destination folder to your chosen vault.</div><div class="export-list">${pack.files.map(f=>`<div class="small mono" style="word-break:break-word">${esc(f)}</div>`).join('')}</div>`;$('#saveFooter').innerHTML='<button class="btn" data-action="close">Back to editor</button><button class="primary" data-action="redownload">Download again</button>';downloadBlob(pack.blob,pack.name)}
async function downloadPackage(){if(ui.exporting)return;let poster;try{const title=$('#exportTitle').value.trim(),vault=$('#exportVault').value.trim(),folder=safeFolder($('#exportFolder').value);if(!title||!vault)throw new Error('Give the tutorial and destination vault a name.');const before=deep(project);project.title=title;project.destination={...project.destination,vault,folder};validate(project);pushHistory(before,'Edit export details');setRenderContext();poster=await rangePoster(lastRenderContext.range);const includeSources=$('#includeSources').checked;if(!$('#includeVideo').checked){$('#saveFooter').innerHTML='<span class="small muted">Preparing package…</span>';showReady(await packageFiles(null,'webm',poster,includeSources));render();return}const health=projectHealth();if(health.missing.length||!health.clips||!health.hasVideo||lastRenderContext.range.end_ms-lastRenderContext.range.start_ms>180000)throw new Error('Resolve the export readiness issues first.');const mime=supportedMime();if(!mime)throw new Error('Video rendering is not available in this browser.');setupAudio();await audioCtx.resume();pause();const out=document.createElement('canvas');out.width=W;out.height=H;const g=out.getContext('2d');const stream=out.captureStream(30);const audioTrack=recordBus.stream.getAudioTracks()[0];if(audioTrack)stream.addTrack(audioTrack);const recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:4500000,audioBitsPerSecond:128000}),chunks=[];exportJob={recorder,stream,canvas:out,ctx:g,chunks,mime,poster,includeSources,start:lastRenderContext.range.start_ms,end:lastRenderContext.range.end_ms,returnTime:ui.time,cancelled:false};ui.exporting=true;ui.time=exportJob.start;ui.playing=false;$('#saveTitle').textContent='Rendering your tutorial';$('#saveBody').innerHTML=`<div class="callout"><b>Keep this window visible.</b><br>Compositing ${project.tracks.filter(t=>t.kind==='video'&&t.visible).length} visible video tracks and the audio mix in real time. Your edit remains untouched.</div><div class="row between"><span class="small">Rendering · ${fmt(exportJob.end-exportJob.start,true)}</span><span class="mono" id="exportPercent">0%</span></div><div class="progress"><i id="exportProgress"></i></div><p class="field-help">The browser may skip frames under load. This is a review output; native rendering is required for production delivery.</p>`;$('#saveFooter').innerHTML='<button class="btn" data-action="cancelExport">Cancel render</button>';recorder.ondataavailable=ev=>{if(ev.data.size)chunks.push(ev.data)};recorder.onerror=ev=>cancelExport('The browser encoder failed. Your edit is still available.');recorder.onstop=async()=>{const job=exportJob;if(!job)return;cleanupExport(job);exportJob=null;if(job.cancelled)return;try{$('#saveTitle').textContent='Packaging files…';let blob=new Blob(job.chunks,{type:job.mime});if(job.mime.includes('webm'))blob=await withWebmDuration(blob,job.end-job.start);if(blob.size<100)throw new Error('The encoder produced an empty video.');showReady(await packageFiles(blob,job.mime.includes('mp4')?'mp4':'webm',job.poster,job.includeSources))}catch(e){toast(e.message);openSave()}};syncMedia(true);paint(g,false);await Promise.all(activeClips().map(c=>{const r=runtime(c);if(!r||r.el.readyState>=2&&!r.el.seeking)return Promise.resolve();return new Promise(resolve=>{r.el.addEventListener('canplay',resolve,{once:true});r.el.addEventListener('seeked',resolve,{once:true});setTimeout(resolve,1500)})}));if(!exportJob||exportJob.cancelled)return;paint(g,false);await play(true)}catch(e){if(exportJob)cancelExport(e.message);else{const el=$('#exportError');if(el)el.textContent=e.message;else toast(e.message)}}}
function cleanupExport(job){pause();job.stream.getVideoTracks().forEach(t=>t.stop());ui.exporting=false;ui.time=clamp(job.returnTime,0,duration());render();syncMedia(true)}
function finishRecording(){const job=exportJob;if(!job||job.finishing)return;job.finishing=true;pause();if(job.recorder.state!=='inactive')job.recorder.stop()}
function cancelExport(message='Render cancelled. Your timeline and originals are unchanged.'){const job=exportJob;if(!job){$('#saveDialog').close();return}job.cancelled=true;pause();if(job.recorder.state!=='inactive')job.recorder.stop();else{cleanupExport(job);exportJob=null}$('#saveDialog').close();toast(message)}
function trackMenu(anchor){const r=anchor.getBoundingClientRect(),menu=$('#menu');menu.innerHTML=`<button data-add-track="video">${svg('video')}Add video track</button><button data-add-track="audio">${svg('music')}Add audio track</button>`;menu.style.left=Math.min(innerWidth-200,r.left)+'px';menu.style.top=Math.min(innerHeight-90,r.bottom+5)+'px';menu.hidden=false;menu.querySelector('button').focus()}
function route(action,el){if(ui.exporting&&!['cancelExport','close'].includes(action))return;switch(action){case'play':play();break;case'start':seek(0);break;case'end':seek(duration());break;case'undo':undo();break;case'redo':redo();break;case'split':split();break;case'delete':deleteSelection();break;case'deselect':ui.selected=null;render();break;case'duplicate':duplicateClip();break;case'earlier':reorderClip(-1);break;case'later':reorderClip(1);break;case'snap':ui.snap=!ui.snap;render();break;case'fit':ui.zoom=1;$('#timelineScroll').scrollLeft=0;renderTimeline();$('#zoomRange').value=1;break;case'zoomIn':ui.zoom=clamp(ui.zoom+.5,1,32);renderTimeline();$('#zoomRange').value=ui.zoom;break;case'zoomOut':ui.zoom=clamp(ui.zoom-.5,1,32);renderTimeline();$('#zoomRange').value=ui.zoom;break;case'appMenu':{const menu=$('#menu'),r=el.getBoundingClientRect();menu.innerHTML='<button data-action=theme>Switch theme</button><button data-action=help>Help & shortcuts</button><button data-action=downloadProject>Save project…</button><button data-action=openProject>Open project…</button><button data-action=reset>Restore sample…</button>';menu.style.left=Math.min(innerWidth-205,r.left)+'px';menu.style.top=(r.bottom+5)+'px';menu.hidden=false;menu.querySelector('button').focus();break}case'theme':document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';try{localStorage.setItem(STORAGE+'.theme',document.documentElement.dataset.theme)}catch{}break;case'help':openDialog('#helpDialog');break;case'review':pause();ui.review=!ui.review;render();break;case'save':openSave();break;case'health':openSave(true);break;case'close':closeDialog(el.closest('dialog'));break;case'downloadPackage':downloadPackage();break;case'cancelExport':cancelExport();break;case'redownload':if(lastPackage)downloadBlob(lastPackage.blob,lastPackage.name);break;case'import':$('#mediaInput').click();break;case'openProject':$('#projectInput').click();break;case'downloadProject':downloadProject();break;case'reset':resetDemo();break;case'note':showNote();break;case'downloadNote':downloadBlob(new Blob([noteText()],{type:'text/markdown'}),safeBase(project.title)+'.md');break;case'marker':addMarker();break;case'snapshot':snapshot();break;case'trackMenu':trackMenu(el);break;case'removeTrack':if(ui.selected?.type==='track')deleteTrack(ui.selected.id);break;case'trackUp':if(ui.selected?.type==='track')moveTrack(ui.selected.id,-1);break;case'trackDown':if(ui.selected?.type==='track')moveTrack(ui.selected.id,1);break;case'previewFade':{const c=selectedClip();if(c){seek(c.start_ms);play()}}break;case'mixer':renderMixer();openDialog('#mixerDialog');break;case'monitor':ui.monitorMuted=!ui.monitorMuted;syncMedia();updateTransport();break;case'detachAudio':detachAudio();break;case'rename':promptText('Rename tutorial','Tutorial title',project.title,v=>change(()=>project.title=v,'Rename tutorial'));break;case'inspector':$('#workspace').classList.toggle('inspector-open');break;case'library':if(innerWidth<=800)$('#app').classList.toggle('library-drawer');else $('#workspace').classList.toggle('library-hidden');fitCanvas();break}}
document.addEventListener('click',ev=>{const target=ev.target.closest('button,[data-tab],[data-property-tab],[data-clip],[data-fx]');if(!target){if(!ev.target.closest('#menu'))$('#menu').hidden=true;return}if(ui.exporting&&!['close','cancelExport'].includes(target.dataset.action))return;const d=target.dataset;if(d.action){route(d.action,target);if(!['trackMenu','appMenu'].includes(d.action))$('#menu').hidden=true;return}$('#menu').hidden=true;if(d.tab){ui.tab=d.tab;render();return}if(d.propertyTab){ui.propertyTab=d.propertyTab;renderInspector();return}if(d.effect){addEffect(d.effect);return}if(d.addAsset){addAsset(d.addAsset);return}if(d.relink){relinkId=d.relink;$('#relinkInput').click();return}if(d.addTrack){addTrack(d.addTrack);return}if(d.toggleTrack){toggleTrack(d.toggleTrack,d.key);return}if(d.selectTrack){ui.selected={type:'track',id:d.selectTrack};renderInspector();renderTimeline();return}if(d.seek!==undefined){seek(Number(d.seek));return}if(d.editMarker){const m=project.markers.find(m=>m.id===d.editMarker);if(!editable(clip(m.clip_id),true))return;promptText('Edit chapter','Chapter title',m.title,v=>change(()=>m.title=v,'Rename chapter'));return}if(d.color){const e=project.effects.find(e=>e.id===ui.selected?.id);if(e&&editable(clip(e.clip_id),true))change(()=>e.color=d.color,'Change annotation color');return}if(d.fadePreset!==undefined){const c=selectedClip();if(!editable(c))return;change(()=>c.fade_in_ms=c.fade_out_ms=Math.min(Number(d.fadePreset),clipDuration(c)/2),'Apply fade preset');return}if(d.crossfade){makeCrossfade(Number(d.crossfade));return}if(d.removeTransition){removeTransition(d.removeTransition);return}if(d.transition){const tr=project.transitions.find(t=>t.id===d.transition);ui.selected={type:'clip',id:tr.from};ui.propertyTab='fades';renderInspector();return}if(d.layout){const c=selectedClip();if(!editable(c,true))return;change(()=>{if(d.layout==='full'){c.x=c.y=0;c.w=c.h=1}else{c.x=.67;c.y=.12;c.w=c.h=.29}},'Change video layout');return}if(ev.detail===0&&d.clip)selectClip(d.clip);if(ev.detail===0&&d.fx)selectEffect(d.fx)});
document.addEventListener('change',ev=>{const el=ev.target;if(el.dataset.prop){propChange(el);return}if(el.dataset.trackGain){const t=track(el.dataset.trackGain),resume=ui.playing;change(()=>t.volume=Number(el.value),'Change track level');renderMixer();if(resume)play();return}if(el.id==='masterGain'){const resume=ui.playing;change(()=>project.master_gain=Number(el.value),'Change master level');renderMixer();if(resume)play();return}if(el.id==='playbackRate'){ui.rate=Number(el.value);syncMedia();return}if(el.id==='mediaInput'){importFiles([...el.files]);el.value='';return}if(el.id==='projectInput'){if(el.files[0])openProjectFile(el.files[0]);el.value='';return}if(el.id==='relinkInput'){if(el.files[0])relinkFile(el.files[0]);el.value='';return}});
$('#zoomRange').addEventListener('input',ev=>{ui.zoom=Number(ev.target.value);renderTimeline()});
// Built-in modal elements keep focus inside the active dialog and restore it to the trigger.
$$('dialog').forEach(d=>{d.addEventListener('cancel',ev=>{if(d.id==='saveDialog'&&ui.exporting){ev.preventDefault();cancelExport()}});d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)closeDialog(d)}})});
document.addEventListener('keydown',ev=>{const editing=ev.target.closest('input,textarea,select,[contenteditable=true]');if(ev.key==='Escape'){if(drag){ev.preventDefault();finishDrag(true)}if(previewDrag){ev.preventDefault();finishPreviewDrag(true)}$('#menu').hidden=true;return}if(editing||document.querySelector('dialog[open]')||ui.exporting)return;const cmd=ev.ctrlKey||ev.metaKey;if(cmd&&ev.key.toLowerCase()==='s'){ev.preventDefault();downloadProject();return}if(cmd&&ev.key.toLowerCase()==='z'){ev.preventDefault();ev.shiftKey?redo():undo();return}if(cmd&&ev.key.toLowerCase()==='y'){ev.preventDefault();redo();return}if(cmd&&ev.key.toLowerCase()==='d'){ev.preventDefault();duplicateClip();return}if(ev.target.id==='resizeBar')return;const key=ev.key.toLowerCase(),nativeButton=ev.target.closest('button');if((key===' '||key==='enter')&&nativeButton)return;if(key==='enter'&&ev.target.dataset.clip){ev.preventDefault();selectClip(ev.target.dataset.clip,true);return}if(key==='enter'&&ev.target.dataset.fx){ev.preventDefault();selectEffect(ev.target.dataset.fx);return}if(ev.target.dataset.clip&&['arrowleft','arrowright'].includes(key)){ev.preventDefault();const c=clip(ev.target.dataset.clip);moveClip(c,c.start_ms+(key==='arrowleft'?-1:1)*(ev.shiftKey?1000:1000/30));return}switch(key){case' ':ev.preventDefault();play();break;case's':split();break;case'delete':case'backspace':ev.preventDefault();deleteSelection();break;case'm':addMarker();break;case't':addEffect('text');break;case'v':ui.selected=null;render();break;case'n':ui.snap=!ui.snap;render();break;case'f':route('fit');break;case'+':case'=':route('zoomIn');break;case'-':route('zoomOut');break;case'home':ev.preventDefault();seek(0);break;case'end':ev.preventDefault();seek(duration());break;case'arrowleft':ev.preventDefault();seek(ui.time-(ev.shiftKey?1000:1000/30));break;case'arrowright':ev.preventDefault();seek(ui.time+(ev.shiftKey?1000:1000/30));break;case'?':route('help');break}});
window.addEventListener('resize',()=>{setTimelineHeight($('.timeline').getBoundingClientRect().height);fitCanvas();renderTimeline()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&ui.exporting)cancelExport('Rendering stopped because the page became hidden. Keep the window visible and retry.');else if(document.hidden)pause()});

