async function init(){decorate();$('#shortcutList').innerHTML=[['Space','Play / pause'],['S','Split selected clip'],['Delete','Delete using the selected gap behavior'],['Ctrl / ⌘ Z','Undo'],['Ctrl / ⌘ Shift Z','Redo'],['Ctrl / ⌘ S','Download editable project'],['Ctrl / ⌘ D','Duplicate clip'],['M','Add a chapter'],['N','Toggle snapping'],['F','Fit timeline'],['← / →','Step playhead (Shift = 1 second)'],['Clip focused + ← / →','Nudge clip (Shift = 1 second)'],['Escape','Cancel drag / close dialog']].map(([k,d])=>`<div class="row between" style="padding:5px 0"><span class="small sub">${d}</span><kbd>${k}</kbd></div>`).join('');try{const theme=localStorage.getItem(STORAGE+'.theme');if(theme==='light'||theme==='dark')document.documentElement.dataset.theme=theme;const raw=localStorage.getItem(STORAGE);if(raw){const saved=JSON.parse(raw);project=validate(saved.project);ui.time=clamp(saved.time||0,0,duration());ui.selected=null;$('#saveStatus').innerHTML='<i class="dot"></i>Draft restored locally'}}catch{}prepareBuiltin();render();await restoreMedia();syncMedia();scheduleSave();new ResizeObserver(()=>fitCanvas()).observe($('#stage'));}

